package db

import (
	"database/sql"
	"fmt"
	"os"
	"testing"

	_ "github.com/glebarez/go-sqlite"
	"github.com/juanfont/headscale/hscontrol/types"
)

// Throwaway: boot a fresh migrated sqlite DB and dump sqlite_master so we can
// reconcile schema.sql. NewHeadscaleDatabase returns the squibble error, but
// the DB file is fully migrated by then, so we read it anyway.
func TestZZDumpSchema(t *testing.T) {
	dbPath := os.Getenv("DUMP_DB_PATH")
	if dbPath == "" {
		t.Skip("set DUMP_DB_PATH to run")
	}
	_, _ = NewHeadscaleDatabase(&types.Config{
		Database: types.DatabaseConfig{
			Type:   "sqlite3",
			Sqlite: types.SqliteConfig{Path: dbPath},
		},
		Policy: types.PolicyConfig{Mode: types.PolicyModeDB},
	})

	conn, err := sql.Open("sqlite", dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()

	rows, err := conn.Query(`SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY CASE type WHEN 'table' THEN 0 ELSE 1 END, name`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	for rows.Next() {
		var typ, name, s string
		if err := rows.Scan(&typ, &name, &s); err != nil {
			t.Fatal(err)
		}
		fmt.Printf("\n-- %s %s\n%s;\n", typ, name, s)
	}
}

